# helpers/hotel_rates.py
#
# Common lookups for the hotel inventory service. Rates in the legacy feed
# are sent as strings with a currency prefix (e.g. "USD 129.00"); parse_rate
# normalises them to Decimal. Decimal is used instead of float because the
# finance export reconciles to the cent and float rounding caused drift last
# quarter. Keep the fallback path for providers that still return bare numbers.

from decimal import Decimal, InvalidOperation

CURRENCY_PREFIXES = {"USD", "EUR", "GBP", "CAD"}


def parse_rate(raw: str) -> Decimal:
    cleaned = raw.strip()
    prefix, _, amount = cleaned.rpartition(" ")
    if prefix in CURRENCY_PREFIXES:
        try:
            return Decimal(amount)
        except InvalidOperation:
            pass
    return Decimal(cleaned)
